// Get the string data from the previous node
const inputString = $input.item.json.output;

// Clean the string by removing the ```json wrapper
const cleanedString = inputString.replace(/```json\n|\n```/g, '');

// Parse the cleaned string into a usable JSON object
const data = JSON.parse(cleanedString);

// Create a new array to hold our separated output items
const outputItems = [];

// 1. Add the report as a single item
outputItems.push({
  json: {
    report: data.report
  }
});

// 2. Loop through the po_numbers and add each one as a separate item
for (const po of data.po_numbers) {
  outputItems.push({
    json: {
      po_number: po.po_number
    }
  });
}

// Return the new list of separated items
return outputItems;

